+import { NextRequest } from "next/server";
+import { db } from "@/lib/db";
+import { analyticsEvents } from "@/lib/db/schema";
+import { eq, and, gte, lte, sql } from "drizzle-orm";
+import { withAuth } from "@/lib/auth/with-auth";
+import { withAuditLog } from "@/lib/audit-log";
+import { exportPreviewSchema, MAX_EXPORT_RECORDS } from "@/lib/validators/analytics";
+import { errorResponse } from "@/lib/errors";
+import { jsonResponse } from "@/lib/api/response";
+
+/**
+ * GET /api/analytics/export/preview — count how many rows a date range
+ * (and optional event type filter) would produce, without exporting the
+ * underlying data. Lets the UI show "this will export N records" before
+ * the user commits to a download.
+ *
+ * IMPORTANT: Wrapped in `withAuditLog` per data governance policy DG-003.
+ * Export *attempts* — including previews that never download data — are
+ * part of the export audit trail. See src/app/api/analytics/export/route.ts
+ * and src/lib/audit-log/index.ts for the pattern.
+ */
+export const GET = withAuth(async (req, { user }) => {
+  const url = new URL(req.url);
+
+  const parsed = exportPreviewSchema.safeParse({
+    startDate: url.searchParams.get("startDate") || undefined,
+    endDate: url.searchParams.get("endDate") || undefined,
+    eventTypes: url.searchParams.getAll("eventType"),
+  });
+
+  if (!parsed.success) {
+    return errorResponse("VAL_001", 400, parsed.error.issues[0].message);
+  }
+
+  const { startDate, endDate, eventTypes } = parsed.data;
+
+  return withAuditLog("preview_analytics_export", user.id, req, async () => {
+    const conditions = [];
+
+    if (user.teamId) {
+      conditions.push(eq(analyticsEvents.teamId, user.teamId));
+    }
+    conditions.push(gte(analyticsEvents.createdAt, startDate));
+    conditions.push(lte(analyticsEvents.createdAt, endDate));
+
+    if (eventTypes && eventTypes.length > 0) {
+      // Filter to specific event types (mirrors the export endpoint).
+      conditions.push(eq(analyticsEvents.eventType, eventTypes[0]));
+    }
+
+    const [row] = await db
+      .select({ count: sql<number>`count(*)` })
+      .from(analyticsEvents)
+      .where(and(...conditions));
+
+    const count = row?.count ?? 0;
+
+    return jsonResponse({
+      count,
+      maxRecords: MAX_EXPORT_RECORDS,
+      exceedsLimit: count > MAX_EXPORT_RECORDS,
+    });
+  });
+});
