+import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
+import { render, screen, waitFor, within, fireEvent } from "@testing-library/react";
+import { ExportButton } from "./export-button";
+
+function mockFetchOnce(body: unknown, init?: ResponseInit) {
+  return new Response(JSON.stringify(body), {
+    status: 200,
+    headers: { "Content-Type": "application/json" },
+    ...init,
+  });
+}
+
+describe("ExportButton", () => {
+  const startDate = new Date("2024-01-01T00:00:00.000Z");
+  const endDate = new Date("2024-01-31T00:00:00.000Z");
+
+  beforeEach(() => {
+    vi.stubGlobal("fetch", vi.fn());
+    // jsdom doesn't implement these blob URL helpers.
+    URL.createObjectURL = vi.fn(() => "blob:mock-url");
+    URL.revokeObjectURL = vi.fn();
+  });
+
+  afterEach(() => {
+    vi.unstubAllGlobals();
+    vi.restoreAllMocks();
+  });
+
+  it("uses the secondary button variant (read-only/export action)", () => {
+    render(<ExportButton startDate={startDate} endDate={endDate} />);
+    const trigger = screen.getByRole("button", { name: /export/i });
+    // Secondary variant has border-gray-300 (see button.tsx variants).
+    expect(trigger.className).toContain("border-gray-300");
+  });
+
+  it("previews the record count for the selected date range before downloading", async () => {
+    const fetchMock = vi.mocked(fetch);
+    fetchMock.mockResolvedValueOnce(
+      mockFetchOnce({ count: 42, maxRecords: 10000, exceedsLimit: false })
+    );
+
+    render(<ExportButton startDate={startDate} endDate={endDate} />);
+    fireEvent.click(screen.getByRole("button", { name: /export/i }));
+
+    const dialog = await screen.findByRole("dialog");
+    await waitFor(() => expect(within(dialog).getByText(/42/)).toBeInTheDocument());
+
+    const [requestUrl] = fetchMock.mock.calls[0];
+    expect(String(requestUrl)).toContain("/api/analytics/export/preview");
+    expect(String(requestUrl)).toContain("startDate=");
+    expect(String(requestUrl)).toContain("endDate=");
+
+    // Download is enabled once a non-zero, in-limit count is previewed.
+    expect(
+      within(dialog).getByRole("button", { name: /download csv/i })
+    ).not.toBeDisabled();
+  });
+
+  it("disables download when the preview exceeds the export limit", async () => {
+    const fetchMock = vi.mocked(fetch);
+    fetchMock.mockResolvedValueOnce(
+      mockFetchOnce({ count: 50000, maxRecords: 10000, exceedsLimit: true })
+    );
+
+    render(<ExportButton startDate={startDate} endDate={endDate} />);
+    fireEvent.click(screen.getByRole("button", { name: /export/i }));
+
+    const dialog = await screen.findByRole("dialog");
+    await waitFor(() =>
+      expect(
+        within(dialog).getByText(/narrow your date range/i)
+      ).toBeInTheDocument()
+    );
+    expect(
+      within(dialog).getByRole("button", { name: /download csv/i })
+    ).toBeDisabled();
+  });
+
+  it("downloads a CSV file via the export endpoint", async () => {
+    const fetchMock = vi.mocked(fetch);
+    fetchMock.mockResolvedValueOnce(
+      mockFetchOnce({ count: 3, maxRecords: 10000, exceedsLimit: false })
+    );
+    fetchMock.mockResolvedValueOnce(
+      new Response("id,team_id\n1,team_1", {
+        status: 200,
+        headers: { "Content-Type": "text/csv" },
+      })
+    );
+
+    render(<ExportButton startDate={startDate} endDate={endDate} />);
+    fireEvent.click(screen.getByRole("button", { name: /export/i }));
+
+    const dialog = await screen.findByRole("dialog");
+    await waitFor(() =>
+      expect(
+        within(dialog).getByRole("button", { name: /download csv/i })
+      ).not.toBeDisabled()
+    );
+
+    fireEvent.click(
+      within(dialog).getByRole("button", { name: /download csv/i })
+    );
+
+    await waitFor(() => expect(fetchMock).toHaveBeenCalledTimes(2));
+    const [exportUrl, exportInit] = fetchMock.mock.calls[1];
+    expect(exportUrl).toBe("/api/analytics/export");
+    expect(exportInit?.method).toBe("POST");
+    const body = JSON.parse(String(exportInit?.body));
+    expect(body.format).toBe("csv");
+    await waitFor(() => expect(URL.createObjectURL).toHaveBeenCalled());
+  });
+});
